import heapq


def smallest_worst_step(heights: list[list[int]]) -> int:
    rows, cols = len(heights), len(heights[0])
    worst = {(0, 0): 0}                  # smallest worst step known to reach each cell
    heap = [(0, 0, 0)]                   # (worst step so far, row, col)
    while heap:
        w, r, c = heapq.heappop(heap)
        if w > worst[(r, c)]:
            continue                     # stale entry: heapq has no decrease-key
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < rows and 0 <= nc < cols:
                nw = max(w, abs(heights[nr][nc] - heights[r][c]))
                if nw < worst.get((nr, nc), float("inf")):
                    worst[(nr, nc)] = nw     # relax with max instead of +
                    heapq.heappush(heap, (nw, nr, nc))
    return worst[(rows - 1, cols - 1)]
